#include <bits/stdc++.h>
using namespace std;

struct Account {
    mutex m;
    long balance;
    explicit Account(long b) : balance(b) {}
};

void transfer(Account& from, Account& to, long amount) {
    if (&from == &to) return;               // locking the same mutex twice is undefined
    scoped_lock lk(from.m, to.m);           // locks both with deadlock avoidance
    from.balance -= amount;
    to.balance += amount;
}

int main() {
    Account a(1000), b(1000);
    // Opposite directions: a naive lock(from); lock(to) could deadlock here
    thread t1([&] { for (int i = 0; i < 10000; i++) transfer(a, b, 1); });
    thread t2([&] { for (int i = 0; i < 10000; i++) transfer(b, a, 2); });
    t1.join(); t2.join();
    cout << "A = " << a.balance << ", B = " << b.balance << "\n";
    cout << "Total = " << a.balance + b.balance << " (must stay 2000)\n";
}

