import random, time

class DeadlockError(Exception):
    pass

attempts_log = []
calls = {"n": 0}

def run_transaction():
    calls["n"] += 1
    if calls["n"] <= 2:                   # the DB picks us as victim twice
        raise DeadlockError("deadlock detected, transaction rolled back")
    return "committed"

def with_retry(fn, max_tries=5):
    for attempt in range(1, max_tries + 1):
        try:
            return fn()                   # retry the WHOLE transaction
        except DeadlockError as e:
            delay = random.uniform(0, 0.01 * 2 ** attempt)   # jittered backoff
            attempts_log.append("attempt %d failed: %s" % (attempt, e))
            time.sleep(delay)
    raise RuntimeError("giving up after %d tries" % max_tries)

print("Result:", with_retry(run_transaction))
for line in attempts_log:
    print(line)
print("Total attempts:", calls["n"])
